<?php echo form_open(get_uri('warehouses/transfers/save'),['id'=>'warehouse-transfer-form']);echo csrf_field(); ?><div class="modal-header"><h5 class="modal-title">Nuevo traspaso</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row"><div class="col-md-4"><label>Almacén origen</label><?php echo form_dropdown('origin_warehouse_id',$warehouses,'',"class='form-control select2' required"); ?></div><div class="col-md-4"><label>Almacén destino</label><?php echo form_dropdown('destination_warehouse_id',$warehouses,'',"class='form-control select2' required"); ?></div><div class="col-md-4"><label>Fecha</label><input type="datetime-local" name="transfer_date" class="form-control" value="<?php echo date('Y-m-d\TH:i'); ?>" required></div></div><div class="row"><div class="col-md-4"><label>Referencia</label><input class="form-control" name="reference_text"></div><div class="col-md-4"><label>Paquetería</label><input class="form-control" name="carrier"></div><div class="col-md-4"><label>Guía</label><input class="form-control" name="tracking_number"></div></div><label>Observaciones</label><textarea class="form-control" name="notes"></textarea><hr><table class="table" id="transfer-lines"><thead><tr><th>Producto</th><th>Cantidad a enviar</th><th>Notas</th><th></th></tr></thead><tbody><tr><td><?php echo form_dropdown('lines[0][warehouse_product_id]',$products,'',"class='form-control select2' required"); ?></td><td><input class="form-control" name="lines[0][quantity_sent]" inputmode="decimal" required></td><td><input class="form-control" name="lines[0][notes]"></td><td><button type="button" class="btn btn-default remove-line">×</button></td></tr></tbody></table><button type="button" class="btn btn-default" id="add-transfer-line">+ Agregar producto</button><div class="alert alert-info mt10">El borrador no afecta existencias. El origen se descuenta únicamente al despachar; el destino aumenta al recibir.</div></div><div class="modal-footer"><button type="button" class="btn btn-default" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Guardar borrador</button></div><?php echo form_close(); ?><script>$(function(){var i=1,b=$('#transfer-lines tbody'),tpl=b.find('tr:first').clone();$('#add-transfer-line').on('click',function(){var r=tpl.clone();r.find('select,input').each(function(){this.name=this.name.replace('[0]','['+i+']');$(this).val('');});b.append(r);r.find('.select2').select2();i++;});b.on('click','.remove-line',function(){if(b.find('tr').length>1)$(this).closest('tr').remove();});$('#warehouse-transfer-form').appForm({closeModalOnSuccess:false,onSuccess:function(r){location.href=r.redirect;}});});</script>
